codeExample.bad:
/* A small loading spinner flashes 4 times per second; even though it's
   a small element, this fails the stricter no-exception AAA rule */
.loading-spinner {
  animation: blink 0.25s infinite;
}
@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

codeExample.good:
/* The spinner rotates continuously instead of flashing in and out,
   avoiding a flash pattern altogether regardless of size */
.loading-spinner {
  animation: spin 1s linear infinite;
}
@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
